CREATE SCHEMA IF NOT EXISTS clinic_q4; SET search_path TO clinic_q4,public;
CREATE TABLE IF NOT EXISTS patients(patient_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,full_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS doctors(doctor_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,full_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS appointments(appointment_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id INT NOT NULL REFERENCES patients,doctor_id INT NOT NULL REFERENCES doctors,appointment_day DATE NOT NULL,slot_time TIME NOT NULL CHECK(slot_time IN('09:00','10:00','11:00','12:00')),status TEXT NOT NULL CHECK(status IN('BOOKED','ATTENDED','CANCELLED')));
CREATE UNIQUE INDEX IF NOT EXISTS uq_doctor_day_slot_active ON appointments(doctor_id,appointment_day,slot_time) WHERE status<>'CANCELLED';
CREATE TABLE IF NOT EXISTS clinic_summary(summary_date DATE PRIMARY KEY,booked_count BIGINT NOT NULL,attended_count BIGINT NOT NULL,cancelled_count BIGINT NOT NULL);
INSERT INTO patients VALUES(1,'Patient One'),(2,'Patient Two'),(3,'Patient Three') ON CONFLICT DO NOTHING;
INSERT INTO doctors VALUES(1,'Dr Green'),(2,'Dr Brown'),(3,'Dr White') ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION fn_daily_load(p_doctor_id INT,p_day DATE) RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE n BIGINT; BEGIN IF NOT EXISTS(SELECT 1 FROM doctors WHERE doctor_id=p_doctor_id) THEN RAISE EXCEPTION 'Unknown doctor'; END IF; SELECT count(*) INTO n FROM appointments WHERE doctor_id=p_doctor_id AND appointment_day=p_day AND status<>'CANCELLED'; RETURN n; END $$;
CREATE OR REPLACE FUNCTION fn_check_appointment_clash() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF NEW.status<>'CANCELLED' AND EXISTS(SELECT 1 FROM appointments a WHERE a.doctor_id=NEW.doctor_id AND a.appointment_day=NEW.appointment_day AND a.slot_time=NEW.slot_time AND a.status<>'CANCELLED' AND a.appointment_id IS DISTINCT FROM NEW.appointment_id) THEN RAISE EXCEPTION 'Doctor already has an appointment in that slot'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_check_appointment_clash ON appointments;
CREATE TRIGGER trg_check_appointment_clash BEFORE INSERT OR UPDATE ON appointments FOR EACH ROW EXECUTE FUNCTION fn_check_appointment_clash();
CREATE OR REPLACE PROCEDURE pr_book_appointment(p_patient_id INT,p_doctor_id INT,p_day DATE,p_slot TIME) LANGUAGE plpgsql AS $$
BEGIN IF NOT EXISTS(SELECT 1 FROM patients WHERE patient_id=p_patient_id) THEN RAISE EXCEPTION 'Unknown patient'; END IF; IF NOT EXISTS(SELECT 1 FROM doctors WHERE doctor_id=p_doctor_id) THEN RAISE EXCEPTION 'Unknown doctor'; END IF; IF p_day<CURRENT_DATE OR p_day IS NULL THEN RAISE EXCEPTION 'Appointment date cannot be in the past'; END IF; IF p_slot NOT IN('09:00','10:00','11:00','12:00') THEN RAISE EXCEPTION 'Unsupported slot'; END IF; INSERT INTO appointments(patient_id,doctor_id,appointment_day,slot_time,status) VALUES(p_patient_id,p_doctor_id,p_day,p_slot,'BOOKED'); END $$;
INSERT INTO appointments(patient_id,doctor_id,appointment_day,slot_time,status) VALUES(1,1,CURRENT_DATE+1,'09:00','BOOKED'),(2,1,CURRENT_DATE+1,'10:00','BOOKED'),(3,2,CURRENT_DATE+1,'09:00','BOOKED'),(1,2,CURRENT_DATE+1,'10:00','ATTENDED'),(2,3,CURRENT_DATE+1,'11:00','CANCELLED'),(3,3,CURRENT_DATE+1,'12:00','BOOKED') ON CONFLICT DO NOTHING;
CREATE OR REPLACE VIEW v_today_appointments AS SELECT a.appointment_id,p.full_name AS patient_name,d.full_name AS doctor_name,a.slot_time FROM appointments a JOIN patients p USING(patient_id) JOIN doctors d USING(doctor_id) WHERE a.appointment_day=CURRENT_DATE AND a.status='BOOKED';
CREATE INDEX IF NOT EXISTS ix_appointments_day_doctor ON appointments(appointment_day,doctor_id);
EXPLAIN SELECT * FROM appointments WHERE appointment_day=CURRENT_DATE AND doctor_id=1;
CREATE OR REPLACE PROCEDURE pr_refresh_clinic_summary(p_day DATE) LANGUAGE plpgsql AS $$
BEGIN INSERT INTO clinic_summary SELECT p_day,count(*) FILTER(WHERE status='BOOKED'),count(*) FILTER(WHERE status='ATTENDED'),count(*) FILTER(WHERE status='CANCELLED') FROM appointments WHERE appointment_day=p_day ON CONFLICT(summary_date) DO UPDATE SET booked_count=EXCLUDED.booked_count,attended_count=EXCLUDED.attended_count,cancelled_count=EXCLUDED.cancelled_count; END $$;
CALL pr_refresh_clinic_summary(CURRENT_DATE);
-- Schedule daily at 01:00 for previous day: CALL clinic_q4.pr_refresh_clinic_summary(CURRENT_DATE-1).
SELECT * FROM v_today_appointments; SELECT fn_daily_load(1,CURRENT_DATE+1);